WITH flattened_attrs AS (SELECT id, status_code, payload_json, CAST((status_code & 4) != 0 AS INT) AS flag_bit4, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs WHERE status_code < 272) SELECT *, ROW_NUMBER() OVER (ORDER BY flag_bit4, id) AS event_seq, AVG(flag_bit4) OVER (ORDER BY retry_count, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS flag_bit4_avg_2_prior, ROW_NUMBER() OVER (ORDER BY flag_bit4 DESC, id) AS seq_no, LEAD(retry_count, 1) OVER (ORDER BY status_code, id) AS next_retry_count FROM flattened_attrs
